import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const file=(p)=>readFileSync(p,'utf8');
const admin=file('app/admin/pay/page.tsx');
const readiness=file('app/api/admin/pay/readiness/route.ts');
const green=file('app/green/page.tsx');
const policy=file('docs/ZESHU_PAY_ROLLOUT_2026-11-21.md');
assert(admin.includes('const purchasedEzytmHits=20_000'),'Owner-reported 20k annual plan must be explicit');
assert(admin.includes('Hits already used (copy manually from Ezytm account)'),'Never misrepresent balance as live');
assert(admin.includes('Calendar days left until actual expiry'),'Do not invent expiry date');
assert(admin.includes('hitPlan.conservativeDailyBudget'),'Make hit budgeting useful without provider calls');
assert(admin.includes('Number.isSafeInteger(used)')&&admin.includes('Number.isSafeInteger(days)'),'Require bounded whole-number inputs');
assert(admin.includes('Never')===false || admin.includes('never sends a request'),'Quota estimator does not contact paid provider');
assert(admin.includes('estimatePayContribution('),'Preserve the independent profit calculator');
assert(readiness.includes('providerCallPerformed:false'),'Provider readiness must not use billable hits');
assert(readiness.includes('liveTransactionEnabled:false'),'A1Topup must stay fail-closed');
assert(readiness.includes('transactionsEnabled:false'),'Ezytm is discovery only');
assert(green.includes('Zeshu Green is on hold'),'No tree planting claims while owner paused');
assert(policy.includes('owner reports an **A1Topup Platinum** subscription'),'Document existing paid plan');
assert(policy.includes('20,000 lookup hits'),'Account for already-paid Ezytm budget');
assert(policy.includes('owner pause remains intact'),'Do not treat existing subscriptions as tree funding');
assert(!admin.includes('window.localStorage'),'Manual quota estimates should not persist in browser');
console.log('PASS: existing A1Topup/Ezytm subscriptions recognized, offline 20k-hit estimator, no paid calls or Green reactivation.');
